-- ═══ Tabela combinada CARVALIMA 2026 (origem CAMPO GRANDE) — rodar no SQL Editor do projeto de CAMPO GRANDE (gfcampogrande) ═══
-- Fonte: "GF MEDICAL TABELAS CARVALIMA 2026.pdf" — 34 rotas: MS para 16 estados (capital/interior) + dentro de MS. Pode rodar mais de uma vez.
-- Interestadual: maior entre minimo / % NF / R$ kg; + despacho 11,00 + TAS 4,00; GRIS 0,25% (min 3,00) + ADV 0,25%; pedagio 4,00 por 100 kg; cubagem 300 kg/m3; ICMS fora do preco.
-- Dentro de MS: maior entre minimo / 1% NF / 0,50 kg; + entrega 3,00; coleta 3,00; GRIS 0,50% (min 3,00); pedagio 2,00 por 100 kg; ICMS fora do preco.
alter table public.frete_tabelas
  add column if not exists cubagem_kg_m3     numeric(8,2),
  add column if not exists pedagio_valor     numeric(12,2),
  add column if not exists pedagio_fracao_kg numeric(10,2),
  add column if not exists gris_pct          numeric(8,4),
  add column if not exists gris_min          numeric(12,2),
  add column if not exists coleta_valor      numeric(12,2),
  add column if not exists icms_modo         text not null default 'incluso',
  add column if not exists icms_pct          numeric(5,2),
  add column if not exists vigencia_fim      date,
  add column if not exists origens           text,
  add column if not exists destinos          text;
alter table public.frete_tabelas add column if not exists calculo text not null default 'soma';   -- 'soma' | 'maior'
alter table public.frete_tabelas add column if not exists adicional_pct numeric(6,3);
-- tabela anterior da Carvalima em Campo Grande deixa de valer a partir de hoje (fica no histórico)
update public.frete_tabelas set vigencia_fim = date '2026-10-26' where transportadora = 'CARVALIMA' and filial = 'CGR' and (vigencia_inicio is null or vigencia_inicio < date '2026-10-27') and vigencia_fim is null;
delete from public.frete_tabelas where transportadora = 'CARVALIMA' and filial = 'CGR' and vigencia_inicio = date '2026-10-27';
insert into public.frete_tabelas (transportadora, rota, origens, destinos, peso_ate, nf_ate, valor_fixo, valor_kg, pct_nf, frete_minimo, minimo_base, calculo, cubagem_kg_m3,
  pedagio_valor, pedagio_fracao_kg, gris_pct, gris_min, coleta_valor, adicional_pct, icms_modo, icms_pct, vigencia_inicio, vigencia_fim, observacoes, filial)
select 'CARVALIMA', v.rota, null, v.destinos, null, null, v.fixo::numeric, v.kg::numeric, v.pct::numeric, v.minimo::numeric, 'total', 'maior', 300,
