insert into public.frete_transportadoras (nome, modal, observacoes, filial)
select 'CARVALIMA', 'Rodoviário', 'CARVALIMA TRANSPORTES LTDA', 'CGR'
where not exists (select 1 from public.frete_transportadoras t where t.filial = 'CGR' and upper(t.nome) = 'CARVALIMA');
notify pgrst, 'reload schema';

select count(*) as linhas, count(*) filter (where destinos is not null) as capitais from public.frete_tabelas where transportadora = 'CARVALIMA' and filial = 'CGR' and vigencia_inicio = date '2026-10-27';
